dtsPropsFor.Button:
/** Visual style. `primary` is the blue brand button, `dark` the near-black one, `light` white-on-blue for use on blue surfaces, `ghost` a grey secondary, `danger` / `outline-danger` destructive. */
variant?: "primary" | "dark" | "light" | "ghost" | "danger" | "outline-danger";
/** `sm` is the compact table-action size. */
size?: "md" | "sm";
/** Tighter padding used inside the site header. */
nav?: boolean;
/** Stretch to the container width. */
fullWidth?: boolean;
/** Trailing icon; the brand uses the diagonal arrow on calls to action. */
icon?: "none" | "arrow-up-right" | "arrow-down";
/** Renders an `<a>` instead of a `<button>`. */
href?: string;
target?: string;
/** Defaults to `button`; pass `submit` inside forms. */
type?: "button" | "submit" | "reset";
disabled?: boolean;
onClick?: () => void;
children: React.ReactNode;
className?: string;
id?: string;
style?: CSSProperties;

dtsPropsFor.Input:
/** `light` white admin input, `on-blue` translucent input for the blue contact band. */
tone?: "light" | "on-blue";
/** `checkbox` renders the compact brand-blue checkbox. */
type?: "text" | "email" | "tel" | "password" | "number" | "date" | "search" | "checkbox" | "hidden";
name?: string;
placeholder?: string;
value?: string;
defaultValue?: string;
checked?: boolean;
defaultChecked?: boolean;
required?: boolean;
disabled?: boolean;
readOnly?: boolean;
minLength?: number;
autoComplete?: string;
onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
className?: string;
id?: string;
style?: CSSProperties;

dtsPropsFor.Textarea:
/** `light` white admin textarea, `on-blue` translucent one for the blue contact band. */
tone?: "light" | "on-blue";
name?: string;
placeholder?: string;
value?: string;
defaultValue?: string;
required?: boolean;
disabled?: boolean;
rows?: number;
onChange?: (event: React.ChangeEvent<HTMLTextAreaElement>) => void;
className?: string;
id?: string;
style?: CSSProperties;

dtsPropsFor.Select:
/** Options rendered as `<option>`s. */
options: Array<{ value: string; label: string }>;
/** `light` white admin select, `on-blue` translucent one for the blue contact band. */
tone?: "light" | "on-blue";
name?: string;
value?: string;
defaultValue?: string;
required?: boolean;
disabled?: boolean;
onChange?: (event: React.ChangeEvent<HTMLSelectElement>) => void;
className?: string;
id?: string;
style?: CSSProperties;

dtsPropsFor.Card:
/** `dashed` marks an "add new" card, `panel` is the large elevated admin panel. */
variant?: "default" | "dashed" | "panel";
/** Optional heading rendered at the top of the card. */
title?: string;
/** Element to render; `form` turns the card into a form (use with `onSubmit`). */
as?: "div" | "section" | "form";
onSubmit?: (event: React.FormEvent<HTMLFormElement>) => void;
children: React.ReactNode;
className?: string;
id?: string;
style?: CSSProperties;

dtsPropsFor.Field:
/** Label text. */
label: string;
/** `stacked` is the larger login-form label; `inline` puts the label beside a checkbox. */
layout?: "default" | "stacked" | "inline";
htmlFor?: string;
/** The control (`Input`, `Select`, `Textarea`, checkbox). */
children: React.ReactNode;
className?: string;
id?: string;
style?: CSSProperties;
